ee:message.ee:set-payload:
%dw 2.0
output application/xml
ns s http://schemas.xmlsoap.org/soap/envelope
ns xsi http://www.w3.org/2001/XMLSchema-instance
ns xsd http://www.w3.org/2001/XMLSchema
var messageResponse = vars.msgResponse."0".payload ++ vars.msgResponse."1".payload ++ vars.msgResponse."2".payload ++ vars.msgResponse."3".payload ++ vars.msgResponse."4".payload ++ vars.msgResponse."5".payload ++ vars.msgResponse."6".payload ++ vars.msgResponse."7".payload ++ vars.msgResponse."8".payload ++ vars.msgResponse."9".payload ++ vars.msgResponse."10".payload ++ vars.msgResponse."11".payload
var allIds = vars.inputPayload.Body.send_message.messages.*message.message_id
var noEvaluated = if (messageResponse.message_id != null)
						(allIds -- messageResponse.message_id) 
							map {
									"message_id": $,
									"status": "delivered",
									"description": "delivered"
								}
                  else
                    allIds map {
									"message_id": $,
									"status": "delivered",
									"description": "delivered"
						    	}
---
{
	s#Envelope: {
        xsi#Body @('xmlns:xsd':"http://www.w3.org/2001/XMLSchema"):{
            send_message_response @(xmlns: "urn:toatech:agent"): 
            {"message_response": ( (messageResponse default []) ++ (noEvaluated default []))}
        }
	}
}

ee:variables.ee:set-variable:
%dw 2.0
output application/json
fun descomponerObj (obj) = obj mapObject ((value, key, index) ->
    if (key as String == "f")
        do{
            var label = key.@n
            ---
            "$label": value
        }else "$key": transformObject(descomponerObj(value))
    )
fun transformObject(obj) =
  obj mapObject ((value, key) ->
      if (key as String == "deinstalled_inventory" or key as String == "installed_inventory")
        "$key": flatten([value] map $.*inventory)
      else {"$key": value}
  )
---
vars.inventoryReturnFilter
    map  ($ mapObject ((value, key, index) ->
            if(key as String == "body")
              "body": descomponerObj(read(value,"application/xml"))
            else "$key": value
        )
    )

ee:message.ee:set-payload:
%dw 2.0
output application/json
---
{
    inbound_interface_request: {
        head: {
            trx_id: vars.payloadParsed.message_id[0],
            component: "Outbound_INVMOVE",
            processing_mode: "appointment_only",
            upload_type: "incremental",
            date: now() >> "America/Bogota",
            appointment: [
                {
                    keys: ["appt_number"]
                }
            ],
            inventory: [
                {
                    keys: ["invsn", "invtype_label"],
                    upload_type: "incremental"
                }
            ],
            properties_mode: "update"
        },
        data: {
            commands: vars.payloadParsed.body.message.*inventory map do{
    var current_quantity = $.current_quantity as Number default 0
var returned_quantity = if (sizeOf($.returned_quantity) == 0) 1 else $.returned_quantity as Number default 0
var quantity = current_quantity - returned_quantity
    ---
     {
            "type": if (quantity > 0) "update_inventory" else "delete_inventory",
            external_id: $.external_id,
            inventories: [
                {
                    properties: [
                        {
                            label: "invsn",
                            value: $.invsn default ""
                        },
                        {
                            label: "invtype_label",
                            value: $.invtype default ""
                        },
                        ({
                            label: "quantity",
                            value: quantity as String
                        }) if (quantity > 0),
                        {
                            label: "XI_Warehouse",
                            value: $.XI_Warehouse default ""
                        },
                        {
                            label: "XI_Logistic_Centre",
                            value: $.XI_Logistic_Centre default ""
                        },
                        {
                            label: "XI_Lote",
                            value: $.XI_Lote default ""
                        },
                        {
                            label: "XI_Material_ID",
                            value: $.XI_Material_ID default ""
                        }
                    ],
                    userdata: ""
                }
            ]
        }
}
        }
    }
}

%dw 2.0
output application/json
---
if (payload.inbound_interface_response.data.commands.report.result == "success") [	
	{	
			message_id : vars.payloadParsed.message_id[0],
			status: "delivered",
			description: "delivered"
	}
]
else
[	
	{	
			message_id : vars.payloadParsed.message_id[0],
			status: payload.inbound_interface_response.data.commands[0].report[0].result,
			description: payload.inbound_interface_response.data.commands[0].report[0].description
	}
]

%dw 2.0
output application/json
---
[	
	{	
			message_id : vars.payloadParsed.message_id[0],
			status: "failed",
			description: "Error, no se pudo procesar el mensaje."
	}
]

%dw 2.0
output application/json
---
{
  "system": {
    "name": "MULESOFT",
    "correlationId": correlationId,
    "processingServer": "ETB_MDM_Integration_MDM_2" 
  },
  "orderId": payload.body.appt_number,
  "messageId": payload.message_id as Number, 
  "requestDate": now(),
  "requestType": vars.requestType,
  "message": {
    "create_ActualizaTecnico": {
      "inMessageId": payload.message_id, 
      "inApptNumber": payload.body.appt_number,
      "inExternalId": payload.body.external_id,
      "inResourcenName": payload.body.resource_name,
      "inTimeSlot": payload.body.time_slot
    }
  }
}

%dw 2.0
output application/json
---
{
  "PeticionOutboundETAdirect": {
    "EncabezadoMensaje": {
      "IdOrdenETAdirect": payload.body.appt_number,
      "IdMensaje": payload.message_id,
      "FechaPeticion": payload.send_to as LocalDateTime { format: "yyyy-MM-dd HH:mm:ss" } as String { format: "yyyy-MM-dd'T'HH:mm:ss'-05:00'" }
    },
    "DetalleMensaje": {
      "IdRecurso": payload.body.external_id,
      "Servicio": payload.body.XA_Service,
      "TipoPeticion": payload.subject,
      "Observaciones": payload.body.XA_Comments_Order
    }
  }
}

ee:variables.ee:set-variable:
%dw 2.0
output application/json
fun descomponerObj (obj) = obj mapObject ((value, key, index) ->
    if (key as String == "f")
        do{
            var label = key.@n
            ---
            "$label": value
        }else "$key": transformObject(descomponerObj(value))
    )
fun transformObject(obj) =
  obj mapObject ((value, key) ->
      if (key as String == "deinstalled_inventory" or key as String == "installed_inventory")
        "$key": flatten([value] map $.*inventory)
      else {"$key": value}
  )
---
vars.notDoneFilter
    map  ($ mapObject ((value, key, index) ->
            if(key as String == "body")
              "body": descomponerObj(read(value,"application/xml"))
            else "$key": value
        )
    )

ee:message.ee:set-payload:
%dw 2.0
output application/json
var petitionDate = payload.send_to as LocalDateTime { format: "yyyy-MM-dd HH:mm:ss" } as String { format: "yyyy-MM-dd'T'HH:mm:ss'-05:00'" }
---
{
    PeticionOutboundETAdirect: {
        EncabezadoMensaje: {
            IdOrdenETAdirect: payload.body.message.appt_number,
            IdMensaje: payload.message_id,
            FechaPeticion: petitionDate
        },
        DetalleMensaje: {
            IdRecurso: payload.body.message.external_id,
            Servicio: payload.body.message.XA_Service,
            TipoPeticion: payload.subject,
            MotivoPeticion: {
                CodigoMotivo: payload.body.message.XA_Problem_Code,
                RazonMotivo: payload.body.message.XA_NotDone_Reason
            },
            Observaciones: payload.body.message.XA_Comments_Order
        }
    }
}

%dw 2.0
output application/json
---
{
  PeticionOutboundETAdirect: {
    EncabezadoMensaje: {
      IdOrdenETAdirect: payload.body.appt_number,
      IdMensaje: payload.message_id,
      FechaPeticion: payload.send_to as LocalDateTime { format: "yyyy-MM-dd HH:mm:ss" } as String { format: "yyyy-MM-dd'T'HH:mm:ss'-05:00'" }
    },
    DetalleMensaje: {
      (IdRecurso: payload.body.external_id) if(payload.body.external_id != null),
      Servicio: payload.body.XA_Service,
      TipoPeticion: payload.subject,
      (MotivoPeticion:{
          (CodigoMotivo: payload.body.XA_Problem_Code) if (payload.body.XA_Problem_Code != null),
          (Motivo: payload.body.XA_Reason) if (payload.body.XA_Reason != null),
          (RazonMotivo: payload.body.XA_Suspended_Reason) if (payload.body.XA_Suspended_Reason != null)
      }) if (payload.body.XA_Problem_Code != null or payload.body.XA_Reason != null or payload.body.XA_Suspended_Reason != null),
      (Observaciones: payload.body.XA_Comments_Order) if (payload.body.XA_Comments_Order != null)
    }
  }
}

