            SerialEquipoPadre: payload.body.XI_invsn_parent default "",
            PuertoEquipoPadre: payload.body.XI_portnumber default "",
            RevertirAccion: payload.body.XA_revert default "",
            IdRecurso: payload.body.external_id default "",
