ee:message.ee:set-payload:
%dw 2.0
output application/json
var petitionDate = payload.send_to as LocalDateTime { format: "yyyy-MM-dd HH:mm:ss" } as String { format: "yyyy-MM-dd'T'HH:mm:ss'-05:00'" }
var technologyFilter = (p('global.technologies') splitBy "|") contains payload.body.message.XA_Technology_Name
---
if (technologyFilter)
{
    PeticionOutboundETAdirect: {
        EncabezadoMensaje: {
            IdOrdenETAdirect: payload.body.message.appt_number,
            IdMensaje: payload.message_id,
            FechaPeticion: payload.send_to
        },
        DetalleMensaje: {
            TipoPeticion: payload.subject default "",
            Servicio: ""
        }
    },
    Message: write(vars.inputPayload.Body, "application/xml")
}
else
{
    PeticionOutboundETAdirect: {
        EncabezadoMensaje: {
            IdOrdenETAdirect: payload.body.message.appt_number,
            IdMensaje: payload.message_id,
            FechaPeticion: petitionDate
        },
        DetalleMensaje: {
            IdRecurso: payload.body.message.external_id default "",
            Servicio: payload.body.message.XA_Service default "",
            TipoPeticion: payload.subject default "",
            Observaciones: payload.body.message.XA_Comments_Order default ""
        }
    }
}

%dw 2.0
		output application/json
		---
		{
		    values: payload.body -- ["id", "form_name"]
		}
